import React, { useMemo, useState } from 'react';
import cx from 'classnames';
import { Message } from '@memori.ai/memori-api-client/dist/types';
import { useTranslation } from 'react-i18next';
import { Button, Modal, Tooltip } from '@memori.ai/ui';
import { Info } from 'lucide-react';
import IconButton from '../IconButton/IconButton';
import GasStation from '../icons/GasStation';
import {
  BADGE_EMOJI,
  formatCacheHitPercent,
  getCacheHitPercent,
} from '../../helpers/llmUsage';

type ImpactMetricType = 'energy' | 'co2' | 'water';

type LlmUsageEnergyImpact = {
  energy?: number | { source?: string; parsedValue?: number };
  gwp?: number | { source?: string; parsedValue?: number };
  wcf?: number | { source?: string; parsedValue?: number };
};

type MessageLlmUsage = {
  provider?: string;
  model?: string;
  totalInputTokens?: number;
  inputCacheReadTokens?: number;
  inputCacheWriteTokens?: number;
  outputTokens?: number;
  energyImpact?: LlmUsageEnergyImpact;
};

export interface ChatConsumptionDropdownProps {
  history: Message[];
  triggerVariant?: React.ComponentProps<typeof Button>['variant'];
  trigger?:
    | ((
        props: React.ButtonHTMLAttributes<HTMLButtonElement>,
        state: { open: boolean }
      ) => React.ReactElement)
    | React.ReactElement<React.ButtonHTMLAttributes<HTMLButtonElement>>;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  hideTrigger?: boolean;
}

export interface ChatConsumptionContentProps {
  history: Message[];
  showTitle?: boolean;
  className?: string;
}

const getMetricValue = (
  metric?: number | { source?: string; parsedValue?: number }
): number | undefined => {
  if (typeof metric === 'number' && Number.isFinite(metric)) return metric;
  if (!metric || typeof metric !== 'object') return undefined;
  if (
    typeof metric.parsedValue === 'number' &&
    Number.isFinite(metric.parsedValue)
  ) {
    return metric.parsedValue;
  }
  if (typeof metric.source === 'string') {
    const parsed = Number(metric.source);
    if (Number.isFinite(parsed)) return parsed;
  }
  return undefined;
};

const formatMetricValue = (value: number, locale: string): string =>
  new Intl.NumberFormat(locale, {
    minimumFractionDigits: 0,
    maximumFractionDigits: Math.abs(value) >= 1 ? 3 : 4,
  }).format(value);

const formatCountValue = (value: number, locale: string): string =>
  new Intl.NumberFormat(locale, {
    maximumFractionDigits: 0,
  }).format(value);

const formatImpactInReadableUnit = (
  value: number,
  metricType: ImpactMetricType,
  locale: string
): string => {
  const absValue = Math.abs(value);

  if (metricType === 'energy') {
    if (absValue >= 1) return `${formatMetricValue(value, locale)} kWh`;
    const wh = value * 1000;
    if (Math.abs(wh) >= 1) return `${formatMetricValue(wh, locale)} Wh`;
    return `${formatMetricValue(wh * 1000, locale)} mWh`;
  }

  if (metricType === 'co2') {
    if (absValue >= 1) return `${formatMetricValue(value, locale)} kg`;
    const g = value * 1000;
    if (Math.abs(g) >= 1) return `${formatMetricValue(g, locale)} g`;
    return `${formatMetricValue(g * 1000, locale)} mg`;
  }

  if (absValue >= 1) return `${formatMetricValue(value, locale)} L`;
  const ml = value * 1000;
  if (Math.abs(ml) >= 1) return `${formatMetricValue(ml, locale)} mL`;
  return `${formatMetricValue(ml * 1000, locale)} μL`;
};

export const ChatConsumptionContent: React.FC<ChatConsumptionContentProps> = ({
  history,
  showTitle = true,
  className,
}) => {
  const { t, i18n } = useTranslation();
  const currentLocale = i18n.language || navigator.language || 'en';
  const chatLog = useMemo(() => ({ lines: history }), [history]);

  const chatConsumptionTotals = useMemo(() => {
    const totals = {
      totalInputTokens: 0,
      totalOutputTokens: 0,
      totalCacheReadTokens: 0,
      totalCacheWriteTokens: 0,
      energy: 0,
      gwp: 0,
      wcf: 0,
      models: new Set<string>(),
    };

    (chatLog?.lines ?? []).forEach(line => {
      const llmUsage = (
        line as Message & {
          llmUsage?: MessageLlmUsage;
        }
      ).llmUsage;

      if (!llmUsage) return;

      totals.totalInputTokens += llmUsage.totalInputTokens ?? 0;
      totals.totalOutputTokens += llmUsage.outputTokens ?? 0;
      totals.totalCacheReadTokens += llmUsage.inputCacheReadTokens ?? 0;
      totals.totalCacheWriteTokens += llmUsage.inputCacheWriteTokens ?? 0;

      if (llmUsage.provider || llmUsage.model) {
        totals.models.add(
          [llmUsage.provider, llmUsage.model].filter(Boolean).join(' · ')
        );
      }

      if (!llmUsage.energyImpact) return;

      const impact = llmUsage.energyImpact;
      totals.energy += getMetricValue(impact.energy) ?? 0;
      totals.gwp += getMetricValue(impact.gwp) ?? 0;
      totals.wcf += getMetricValue(impact.wcf) ?? 0;
    });

    return totals;
  }, [chatLog]);

  const llmUsageModels = useMemo(
    () => Array.from(chatConsumptionTotals.models),
    [chatConsumptionTotals.models]
  );

  const showCacheRead = chatConsumptionTotals.totalCacheReadTokens > 0;
  const showCacheWrite = chatConsumptionTotals.totalCacheWriteTokens > 0;
  const cacheStatClassName = cx('memori-dropdown--sustainability-stat', {
    'memori-dropdown--sustainability-stat--full':
      showCacheRead !== showCacheWrite,
  });
  const cacheHitPercent = showCacheRead
    ? getCacheHitPercent(
        chatConsumptionTotals.totalCacheReadTokens,
        chatConsumptionTotals.totalInputTokens
      )
    : undefined;

  return (
    <div className={cx('memori-dropdown--sustainability', className)}>
      {showTitle && (
        <h4 className="memori-dropdown--sustainability-title">
          {t('chatLogs.totalChatConsumptionTitle') || 'Consumo Totale Chat'}
        </h4>
      )}
      <div className="memori-dropdown--sustainability-section">
        <h5 className="memori-dropdown--sustainability-section-title">
          {t('chatLogs.modelUsage') || 'Model usage'}
        </h5>
        <div className="memori-dropdown--sustainability-summary">
          <div className="memori-dropdown--sustainability-stat">
            <span className="memori-dropdown--sustainability-stat-label">
              {t('chatLogs.input') || 'Input'}
            </span>
            <strong className="memori-dropdown--sustainability-stat-value">
              {formatCountValue(
                chatConsumptionTotals.totalInputTokens,
                currentLocale
              )}
            </strong>
            <span className="memori-dropdown--sustainability-stat-meta">
              {t('chatLogs.tokens') || 'Tokens'}
            </span>
          </div>
          <div className="memori-dropdown--sustainability-stat">
            <span className="memori-dropdown--sustainability-stat-label">
              {t('chatLogs.output') || 'Output'}
            </span>
            <strong className="memori-dropdown--sustainability-stat-value">
              {formatCountValue(
                chatConsumptionTotals.totalOutputTokens,
                currentLocale
              )}
            </strong>
            <span className="memori-dropdown--sustainability-stat-meta">
              {t('chatLogs.tokens') || 'Tokens'}
            </span>
          </div>
          {showCacheRead && (
            <div className={cacheStatClassName}>
              <span className="memori-dropdown--sustainability-stat-label">
                {t('chatLogs.cacheRead') || 'Cache read'}
              </span>
              <strong className="memori-dropdown--sustainability-stat-value">
                {formatCountValue(
                  chatConsumptionTotals.totalCacheReadTokens,
                  currentLocale
                )}
              </strong>
              <span className="memori-dropdown--sustainability-stat-meta">
                {cacheHitPercent !== undefined ? (
                  <>
                    {formatCacheHitPercent(cacheHitPercent, currentLocale)}
                    <Tooltip
                      title={t('chatLogs.cacheHitTooltip', {
                        defaultValue:
                          'Share of input tokens read from the cache instead of being processed again. A higher value means lower cost and latency.',
                      })}
                      placement="top"
                    >
                      <span
                        className="memori-dropdown--sustainability-stat-info"
                        tabIndex={0}
                        aria-label={t('chatLogs.cacheHit') || 'Cache hit'}
                      >
                        <Info aria-hidden="true" />
                      </span>
                    </Tooltip>
                  </>
                ) : (
                  t('chatLogs.tokens') || 'Tokens'
                )}
              </span>
            </div>
          )}
          {showCacheWrite && (
            <div className={cacheStatClassName}>
              <span className="memori-dropdown--sustainability-stat-label">
                {t('chatLogs.cacheWrite') || 'Cache write'}
              </span>
              <strong className="memori-dropdown--sustainability-stat-value">
                {formatCountValue(
                  chatConsumptionTotals.totalCacheWriteTokens,
                  currentLocale
                )}
              </strong>
              <span className="memori-dropdown--sustainability-stat-meta">
                {t('chatLogs.tokens') || 'Tokens'}
              </span>
            </div>
          )}
        </div>
        {llmUsageModels.length > 0 && (
          <div className="memori-dropdown--sustainability-row memori-dropdown--sustainability-row--stacked">
            <span className="memori-dropdown--sustainability-label">
              {t('chatLogs.provider') || 'Provider'} /{' '}
              {t('chatLogs.model') || 'Model'}
            </span>
            <div className="memori-dropdown--sustainability-tags">
              {llmUsageModels.map(modelLabel => (
                <span
                  key={modelLabel}
                  className="memori-dropdown--sustainability-tag"
                >
                  {modelLabel}
                </span>
              ))}
            </div>
          </div>
        )}
      </div>
      <div className="memori-dropdown--sustainability-metrics">
        <h5 className="memori-dropdown--sustainability-section-title">
          {t('chatLogs.environmentalImpact') || 'Environmental impact'}
        </h5>
        <div className="memori-dropdown--sustainability-row">
          <span className="memori-dropdown--sustainability-label">
            <span aria-hidden="true">{BADGE_EMOJI.energy}</span>{' '}
            {t('chatLogs.energy') || 'Energy'}
          </span>
          <strong className="memori-dropdown--sustainability-value">
            {formatImpactInReadableUnit(
              chatConsumptionTotals.energy,
              'energy',
              currentLocale
            )}
          </strong>
        </div>
        <div className="memori-dropdown--sustainability-row">
          <span className="memori-dropdown--sustainability-label">
            <span aria-hidden="true">{BADGE_EMOJI.co2}</span>{' '}
            {t('chatLogs.co2') || 'CO2'}
          </span>
          <strong className="memori-dropdown--sustainability-value">
            {formatImpactInReadableUnit(
              chatConsumptionTotals.gwp,
              'co2',
              currentLocale
            )}
          </strong>
        </div>
        <div className="memori-dropdown--sustainability-row">
          <span className="memori-dropdown--sustainability-label">
            <span aria-hidden="true">{BADGE_EMOJI.water}</span>{' '}
            {t('chatLogs.water') || 'Water'}
          </span>
          <strong className="memori-dropdown--sustainability-value">
            {formatImpactInReadableUnit(
              chatConsumptionTotals.wcf,
              'water',
              currentLocale
            )}
          </strong>
        </div>
      </div>
    </div>
  );
};

const ChatConsumptionDropdown: React.FC<ChatConsumptionDropdownProps> = ({
  history,
  triggerVariant = 'ghost',
  trigger,
  open: openProp,
  onOpenChange,
  hideTrigger = false,
}) => {
  const { t } = useTranslation();
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false);
  const isControlled = openProp !== undefined;
  const open = isControlled ? openProp : uncontrolledOpen;
  const setOpen = (next: boolean) => {
    if (!isControlled) {
      setUncontrolledOpen(next);
    }
    onOpenChange?.(next);
  };

  const hasConsumptionData = useMemo(
    () =>
      (history ?? []).some(
        line => !!(line as Message & { llmUsage?: MessageLlmUsage }).llmUsage
      ),
    [history]
  );

  const triggerLabel =
    t('write_and_speak.showMessageConsumptionLabel') || 'Show chat consumption';
  const modalTitle =
    t('chatLogs.totalChatConsumptionTitle') || 'Consumo Totale Chat';
  const renderDefaultTrigger = (
    triggerButtonProps: React.ButtonHTMLAttributes<HTMLButtonElement>
  ) => (
    <Tooltip title={triggerLabel} placement="bottom">
      <span style={{ display: 'inline-flex' }}>
        <IconButton
          {...triggerButtonProps}
          variant={triggerVariant}
          shape="default"
          active={open}
          disabled={triggerButtonProps.disabled ?? !hasConsumptionData}
          className={cx(
            'memori-header--button memori-header--button--sustainability',
            triggerButtonProps.className
          )}
          aria-label={triggerLabel}
          icon={
            <GasStation className="memori-header--button--sustainability-icon" />
          }
        />
      </span>
    </Tooltip>
  );

  const handleTriggerClick: React.MouseEventHandler<
    HTMLButtonElement
  > = event => {
    if (!hasConsumptionData) return;
    setOpen(true);
    event.currentTarget.blur();
  };

  if (!hasConsumptionData) {
    if (hideTrigger || trigger) return null;
    return renderDefaultTrigger({ disabled: true });
  }

  const renderTrigger = (
    triggerButtonProps: React.ButtonHTMLAttributes<HTMLButtonElement>
  ) => {
    if (!trigger) return renderDefaultTrigger(triggerButtonProps);
    if (typeof trigger === 'function')
      return trigger(triggerButtonProps, { open });
    if (
      !React.isValidElement<React.ButtonHTMLAttributes<HTMLButtonElement>>(
        trigger
      )
    ) {
      return renderDefaultTrigger(triggerButtonProps);
    }

    const triggerProps = trigger.props ?? {};
    const mergedClassName = cx(
      triggerButtonProps.className,
      triggerProps.className
    );
    const mergedOnClick: React.MouseEventHandler<HTMLButtonElement> = event => {
      triggerButtonProps.onClick?.(event);
      triggerProps.onClick?.(event);
    };

    return React.cloneElement(trigger, {
      ...triggerProps,
      ...triggerButtonProps,
      className: mergedClassName || undefined,
      onClick: mergedOnClick,
    });
  };

  return (
    <>
      {!hideTrigger &&
        renderTrigger({
          onClick: handleTriggerClick,
        })}
      <Modal
        open={open}
        onClose={() => setOpen(false)}
        title={modalTitle}
        className="memori-chat--usage-modal memori-chat--consumption-modal"
        width="30rem"
        stacking="stacked"
        closable
      >
        <ChatConsumptionContent history={history} showTitle={false} />
      </Modal>
    </>
  );
};

export default ChatConsumptionDropdown;
